    dailyRevenue.add(WETH, protocolShare);

    dailySupplySideRevenue.add(WETH, totalPot * BigInt(85) / BigInt(100));
  }

  return {
    dailyFees,
    dailyRevenue,
    dailyProtocolRevenue,
    dailySupplySideRevenue,
  };
};

